service.method:

INSERT 
  INTO SCFGL (
       HOUSE_CODE
     , COMPANY_CODE
     , CONT_FORM_NO
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , CONT_FORM_NAME
     , CONT_FORM_DESC
     , CONT_METHOD
     , CONT_TYPE
     , DEL_FLAG
     , STATUS
     , SIGNER_CODE
     , USE_FLAG
     , USE_FROM
     , USE_TO
     , CATEGORY
 ) VALUES (
       ${session.HOUSE_CODE}
     , ${session.COMPANY_CODE}
     , ${CONT_NO}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${CONT_FORM_NAME}
     , ${CONT_FORM_DESC}
     , ${CONT_METHOD}
     , ${CONT_TYPE}   
     , 'N'   
     , 'T'
     , ${SIGNER_CODE}
     , 'Y'
     , ${USE_FROM}
     , ${USE_TO}  
     , ${CATEGORY}
 )
